async function loadFin(){if(st.finBusy)return;st.finBusy=true;try{const {doc}=await API.load('finance');st.fin=A(doc?.entries);st.finErr=''}catch(e){st.finErr=e.message}finally{st.finBusy=false;P.render()}}
const srcOpts=(sel,all)=>{const c=CR(),people=A(c?.cashRecipients);return(all?'<option value="">همهٔ منابع</option>':'<option value="">انتخاب کنید</option>')+people.filter(p=>all||p.status!=='غیرفعال').map(p=>`<option value="cash:${esc(p.id)}" ${sel==='cash:'+p.id?'selected':''}>نقد نزد ${esc(p.name)}</option>`).join('')+A(c?.transferAccounts).filter(a=>all||a.status!=='غیرفعال').map(a=>`<option value="account:${esc(a.id)}" ${sel==='account:'+a.id?'selected':''}>کارت ${esc(a.name)}</option>`).join('')};
